async function scanBundle(input, deliver) {
  let count = 0;
  let line = 1;
  let pending = "";

  async function processLine() {
    const text = pending;
    pending = "";

    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${line}`);
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }

    count++;
    return (await deliver(value, line)) !== false;
  }

  try {
    const decoder = new TextDecoder("utf-8");

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        pending += decoder.decode();
        await processLine();
        return count;
      }

      let start = 0;
      while (start < chunk.length) {
        const end = chunk.indexOf(10, start);

        if (end === -1) {
          pending += decoder.decode(chunk.subarray(start), { stream: true });
          break;
        }

        pending += decoder.decode(chunk.subarray(start, end), { stream: true });

        if (!(await processLine())) return count;

        line++;
        start = end + 1;
      }
    }
  } finally {
    await input.close();
  }
}
